public class Solution {
    public static String[] separate_paren_groups(String paren_string) {
        List<String> result = new ArrayList<>();
        List<Character> current_string = new ArrayList<>();
        int current_depth = 0;

        for (char c : paren_string.toCharArray()) {
            if (c == '(') {
                current_depth += 1;
                current_string.add(c);
            } else if (c == ')') {
                current_depth -= 1;
                current_string.add(c);

                if (current_depth == 0) {
                    result.add(toString(current_string));
                    current_string.clear();
                }
            }
       }

        return result.toArray(new String[0]);
    }

    private static String toString(List<Character> list) {
        StringBuilder builder = new StringBuilder(list.size());
        for (char ch : list) {
            builder.append(ch);
        }
        return builder.toString();
    }
}

