public class Solution {
    public static List<Integer> parse_nested_parens(String paren_string) {
        return new Parser().parseGroups(paren_string);
    }

    private static class Parser {
        int parseGroup(String s) {
            int depth = 0;
            int maxDepth = 0;

            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);

                if (c == '(') {
                    depth += 1;
                    maxDepth = Math.max(depth, maxDepth);
               } else {
                    depth -= 1;
                }
            }

            return maxDepth;
        }

        List<Integer> parseGroups(String paren_string) {
            String[] groups = paren_string.split("\\s+");
            List<Integer> depths = new ArrayList<>();

            for (String group : groups) {
                if (!group.isEmpty()) {
                    depths.add(parseGroup(group));
                }
            }

            return depths;
        }
    }
}

