public class Solution {
    public static long[] sumProduct(long[] numbers) {
        long sum = 0;
        long product = 1;

        for (long number : numbers) {
            sum += number;
            if (product > 0 && Long.MAX_VALUE / product < number) {
                // Prevent overflow by returning [0, 0] on overflow
                return new long[]{0, 0};
            }
            product *= number;
        }

        return new long[]{sum, product};
    }
}

