public class Solution {
    public static String make_palindrome(String a0) {
        if (a0 == null || a0.isEmpty()) return "";

        int beginningOfSuffix = 0;

        while (!isPalindrome(a0.substring(beginningOfSuffix))) {
            beginningOfSuffix++;
        }

        String suffix = a0.substring(0, beginningOfSuffix);
        return a0 + new StringBuilder(suffix).reverse().toString();
    }

    private static boolean isPalindrome(String s) {
        int start = 0;
        int end = s.length() - 1;

        while (start < end) {
            if (s.charAt(start) != s.charAt(end)) return false;

            start++;
            end--;
        }

        return true;
    }
}

