public class Solution {
    public static double[] find_closest_elements(double[] numbers) {
        List<Double> closestPair = new ArrayList<>();
        Double distance = null;

        for (int idx = 0; idx < numbers.length; idx++) {
            for (int idx2 = 0; idx2 < numbers.length; idx2++) {
                if (idx != idx2) {
                    if(distance == null){
                        distance = Math.abs(numbers[idx] - numbers[idx2]);
                        closestPair = new ArrayList<>(Arrays.asList(Math.min(numbers[idx], numbers[idx2]), Math.max(numbers[idx], numbers[idx2])));
                    } else {
                        double newDistance = Math.abs(numbers[idx] - numbers[idx2]);
                        if (newDistance < distance) {
                            distance = newDistance;
                            closestPair = new ArrayList<>(Arrays.asList(Math.min(numbers[idx], numbers[idx2]), Math.max(numbers[idx], numbers[idx2])));
                        }
                    }
                }
            }
        }

        return new double[]{closestPair.get(0), closestPair.get(1)};
    }
}

