public class Solution {
    public static long[] remove_duplicates(long[] a0) {
        Map<Long, Integer> countMap = new HashMap<>();

        // Count occurrences of each number in the array
        for (long num : a0) {
            if (!countMap.containsKey(num)) {
                countMap.put(num, 1);
            } else {
                countMap.put(num, countMap.get(num) + 1);
            }
        }

        // Create a new list to hold the unique numbers
        List<Long> uniqueNumbers = new ArrayList<>();

        // Add each number to the list if its occurrence is less than or equal to 1
        for (long num : a0) {
            if (countMap.get(num) <= 1) {
                uniqueNumbers.add(num);
            }
        }

        // Convert List<Long> back to long[] and return it
        long[] result = new long[uniqueNumbers.size()];
        for (int i = 0; i < uniqueNumbers.size(); i++) {
            result[i] = uniqueNumbers.get(i);
        }

        return result;
    }
}

