public class Solution {
    public static long[] sort_even(long[] a0) {
        List<Long> evens = new ArrayList<>();
        List<Long> odds = new ArrayList<>();

        for (int i = 0; i < a0.length; i++) {
            if (i % 2 == 0) {
                evens.add(a0[i]);
            } else {
                odds.add(a0[i]);
            }
        }

        Collections.sort(evens);

        long[] ans = new long[a0.length];
        int e = 0, o = 0;
        for (int i = 0; i < a0.length && e < evens.size() && o < odds.size(); i++) {
            if (i % 2 == 0) {
                ans[i] = evens.get(e++);
            } else {
                ans[i] = odds.get(o++);
            }
        }

        if (evens.size() > odds.size()) {
            ans[ans.length - 1] = evens.get(evens.size() - 1);
        }

        return ans;
    }
}

public class Solution {
    public static String decode_cyclic(String s) {
        return encodeCyclic(encodeCyclic(s));
    }

    private static String encodeCyclic(String s) {
        int length = s.length();

        // split string to groups. Each of length 3.
        StringBuilder[] groups = new StringBuilder[(length + 2) / 3];
        for (int i = 0; i < groups.length; i++) {
            int start = i * 3;
            int end = Math.min(start + 3, length);
            groups[i] = new StringBuilder(s.substring(start, end));

            // cycle elements in each group. Unless group has fewer than 3 characters.
            if (groups[i].length() == 3) {
                char temp = groups[i].charAt(0);
                groups[i].deleteCharAt(0);
                groups[i].append(temp);
            }
       }

        // join the groups back together.
        StringBuilder result = new StringBuilder();
        for (StringBuilder group : groups) {
            result.append(group);
        }
        return result.toString();
    }
}

