public class Solution {
    public static double triangle_area(long a0, long a1, long a2) {
        if (a0 + a1 <= a2 || a0 + a2 <= a1 || a1 + a2 <= a0) {
            return -1;
        } 
        double s = (a0 + a1 + a2)/2.0;    
        double area = Math.sqrt(s * (s-a0) * (s-a1) * (s-a2));
        area = Math.round(area * 100.0) / 100.0;
        return area;
    }
}

