public class Solution {
    public static long[] even_odd_palindrome(long n) {
        long evenPalindromeCount = 0;
        long oddPalindromeCount = 0;

        for (int i = 1; i <= n; i++) {
            if (i % 2 == 1 && isPalindrome(i)) {
                oddPalindromeCount += 1;
            } else if (i % 2 == 0 && isPalindrome(i)) {
                evenPalindromeCount += 1;
           }

        return new long[] {evenPalindromeCount, oddPalindromeCount};
    }

    private static boolean isPalindrome(int n) {
        String str = Integer.toString(n);
        int start = 0;
        int end = str.length() - 1;

        while (start < end) {
            if (str.charAt(start) != str.charAt(end)) {
                return false;
            }

            start++;
            end--;
        }

        return true;
    }
}

