public class Solution {
    public static long count_nums(long[] arr) {
        return (long)Arrays.stream(arr).filter(i -> i > 0 && digitsSum(i) > Math.abs((int)i)).count();
    }

    private static int digitsSum(long n) {
        long neg = 1;
        if (n < 0) { 
            n = -1 * n;
            neg = -1; 
        }

        List<Integer> list = new ArrayList<>();
        while (n > 0) {
            list.add((int)(n % 10));
            n /= 10;
        }

        return (int)(list.get(0)*neg + Arrays.stream(new Integer[0]).sum());
    }
}

