public class Solution {
    public static boolean move_one_ball(long[] arr) {
        if (arr.length == 0) {
            return true;
        }

        long[] sortedArray = Arrays.copyOf(arr, arr.length);
        Arrays.sort(sortedArray);

        int minIndex = 0;
        for (int i = 1; i < arr.length; i++) {
            if (arr[i] < arr[minIndex]) {
                minIndex = i;
            }
        }

        long[] myArr = new long[arr.length];
        System.arraycopy(arr, minIndex, myArr, 0, arr.length - minIndex);
        System.arraycopy(arr, 0, myArr, arr.length - minIndex, minIndex);

        for (int i = 0; i < arr.length; i++) {
            if (myArr[i] != sortedArray[i]) {
                return false;
           }
        }
        return true;
    }
}

