public class Solution {
    public static long[] sort_array(long[] a0) {
        Arrays.sort(a0);

        Map<Long, Integer> bitCountMap = new HashMap<>();
        for (long num : a0) {
            int bitCount = Long.bitCount(num);
            bitCountMap.put(num, bitCount);
        }

        Comparator<Long> comparator = new Comparator<Long>() {
            @Override
            public int compare(Long n1, Long n2) {
                int count1 = bitCountMap.getOrDefault(n1, 0);
                int count2 = bitCountMap.getOrDefault(n2, 0);

                if (count1 == count2) return Long.compare(n1, n2);
                else return Integer.compare(count1, count2);
           }
        };

        Arrays.sort(a0, comparator);

        return a0;
    }
}

