public class Solution {
    public static String intersection(long[] interval1, long[] interval2) {
        boolean isPrime = true;

        long l = Math.max(interval1[0], interval2[0]);
        long r = Math.min(interval1[1], interval2[1]);
        long length = r - l;

        if (length > 0) {
            isPrime = isPrime((int)length);
        }

        return isPrime ? "YES" : "NO";
    }

    private static boolean isPrime(int num) {
        if (num == 1 || num == 0) {
