public class Solution {
    public static boolean is_nested(String string) {
        java.util.List<Integer> openingBracketIndex = new java.util.ArrayList<>();
        java.util.List<Integer> closingBracketIndex = new java.util.ArrayList<>();

        for (int i = 0; i < string.length(); i++) {
            if (string.charAt(i) == '[') {
                openingBracketIndex.add(i);
            } else {
                closingBracketIndex.add(i);
            }
        }

        java.util.Collections.reverse(closingBracketIndex);

        int cnt = 0;
        int i = 0;
        int l = closingBracketIndex.size();

        for (int idx : openingBracketIndex) {
            if (i < l && idx < closingBracketIndex.get(i)) {
                cnt++;
                i++;
            }
        }

        return cnt >= 2;
    }
}

