public class Solution {
    static String fix_spaces(String text) {
        StringBuilder newText = new StringBuilder();
        int i = 0;
        int start = 0, end = 0;
        while (i < text.length()) {
            if (text.charAt(i) == ' ' && i + 1 < text.length() && text.charAt(i+1) == ' ') {
                end++;
            } else {
                newText.append((end - start > 2 ? "-" : "").repeat(Math.max(0, end - start)));
                if (end > start) 
                    newText.append(text.charAt(i));
                start = i + 1;
                end = start;
            }
            i++;
        }
        if (end - start > 2) {
            newText.append("-");
        } else if (end - start > 0) {
            newText.append("_");
        }
        return newText.toString();
    }
}

