                newSentence.append(word).append(" ");
            }
        }

        return newSentence.toString().trim(); // Trim to remove the trailing space
    }

    private static boolean isSpecialWord(String word) {
        int length = word.length();

        if (length == 1 || length % 2 == 0) {
            return true;
        }

        for (int i = 3; i <= Math.sqrt(length); i += 2) {
            if (length % i == 0) {
                return true;
            }
        }

