public class Solution {
    public static String[] bf(String planet1, String planet2) {
        String[] planetNames = {"Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"};

        boolean isPlanet1Valid = false;
        boolean isPlanet2Valid = false;
        int planet1Index = 0;
        int planet2Index = 0;

        for (int i=0; i<planetNames.length; i++) {
            if(planetNames[i].equalsIgnoreCase(planet1)) {
                isPlanet1Valid = true;
                planet1Index = i;
            } 

            if(planetNames[i].equalsIgnoreCase(planet2)) {
                isPlanet2Valid = true;
                planet2Index = i;
           }
        }

        // If either of the planets are not valid or they are same, return an empty array.
        if (!isPlanet1Valid || !isPlanet2Valid || planet1.equalsIgnoreCase(planet2)) {
            return new String[0];
        } 

        ArrayList<String> result = new ArrayList<>();
        // If planet1 is before planet2 in the sequence, add all planets between them to the list.
        if (planet1Index < planet2Index) {
            for(int i=planet1Index+1; i<planet2Index; i++){
                result.add(planetNames[i]);
            }
        // If planet2 is before planet1 in the sequence, add all planets between them to the list.
        } else {
            for(int i=planet2Index+1; i<planet1Index; i++){
                result.add(planetNames[i]);
            }
        }

        // Convert ArrayList back to array and return it.
        String[] res = new String[result.size()];
        res = result.toArray(res);
