public class Solution {
    public static long do_algebra(String[] operator, long[] operand) {
        StringBuilder expression = new StringBuilder(Long.toString(operand[0]));
        for (int i = 1; i < operand.length; i++) {
            expression.append(" ").append(operator[i-1]).append(" ").append(operand[i]);
        }
        return calculateExpression(expression.toString());
    }

    private static long calculateExpression(String expression) {
        String[] parts = expression.split(" ");
        long result = Long.parseLong(parts[0]);

        for (int i = 1; i < parts.length; i += 2) {
            char operator = parts[i].charAt(0);
            long operand = Long.parseLong(parts[i+1]);

            switch (operator) {
                case '+':
                    result += operand;
                    break;
                case '-':
                    result -= operand;
                    break;
                case '*':
                    result *= operand;
                    break;
                case '/':
                    result /= operand;
                    break;
            }
        }

        return result;
    }
}

